import type { MainNavBrandProps } from "../main-nav.types";

import { forwardRef } from "react";
import { clsx } from "clsx";
import { Sidebar as SidebarIcon } from "@exp-textura/icons";

import { MainNavClasses } from "../main-nav.styles";
import { useMainNav } from "../hooks/use-main-nav";

export const MainNavBrand = forwardRef<HTMLAnchorElement, MainNavBrandProps>(
  ({ className, brandImg, squareBrandImg, ...props }, ref) => {
    const { dataMainNavState, collapsed } = useMainNav();

    return (
      <a
        ref={ref}
        className={clsx(MainNavClasses.brand, className)}
        data-main-nav-state={!brandImg ? "collapsed" : dataMainNavState}
        {...props}
      >
        {!collapsed && brandImg ? brandImg : squareBrandImg}
      </a>
    );
  },
);

MainNavBrand.displayName = "MainNav.Brand";

export const MainNavCollapseTrigger = forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement>
>(({ className, children, onClick, ...props }, ref) => {
  const { dataMainNavState, collapsed, setIsCollapsed } = useMainNav();

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    onClick?.(e);
    setIsCollapsed(!collapsed);
  };

  return (
    <button
      ref={ref}
      aria-label="toggle main-nav"
      className={clsx(MainNavClasses.collapseTrigger, className)}
      data-main-nav-state={dataMainNavState}
      onClick={handleClick}
      {...props}
    >
      {children || <SidebarIcon />}
    </button>
  );
});
MainNavCollapseTrigger.displayName = "MainNav.CollapseTrigger";
